"""
scripts/eval/build_golden_dataset.py
─────────────────────────────────────
Generates data/eval/golden_dataset.jsonl — the Phase 1 evaluation set.

Fully local, zero API calls, zero cost. LORE cases are built directly
from the real data/manga_chapters (3).jsonl (verifiably correct expected
anime/chapter, not guessed), and EPISODE_UPDATE cases compute their
expected chapter cap via the app's own episode_to_chapter() so the
"correct answer" is generated by the same logic being tested, guaranteed
consistent. RECOMMEND/TOOL/PERSONA_SWITCH/GENERAL/compound cases are
hand-written against what the app actually supports.

Run:
    python -m scripts.eval.build_golden_dataset

Writes data/eval/golden_dataset.jsonl. Nothing is uploaded anywhere —
this is a pure local file for review before scripts/eval/upload_dataset.py
pushes it to LangSmith.
"""

from __future__ import annotations

import ast
import json
import random
from collections import defaultdict
from pathlib import Path

from config.settings import settings
from src.episode.mapping import episode_to_chapter

random.seed(42)  # reproducible sample selection across runs

OUT_PATH = Path(__file__).resolve().parent.parent.parent / "data" / "eval" / "golden_dataset.jsonl"

SUPPORTED_ANIME = ["Demon Slayer", "Jujutsu Kaisen", "Attack on Titan", "Chainsaw Man"]


# ── LORE cases, built from real chapter data ───────────────────────────────────

def _load_chapters() -> dict[str, list[dict]]:
    by_anime: dict[str, list[dict]] = defaultdict(list)
    with open(settings.MANGA_CHAPTERS_PATH, encoding="utf-8") as f:
        for line in f:
            d = json.loads(line)
            d["chapter_number"] = int(d["chapter_number"])
            try:
                d["key_events"] = ast.literal_eval(d["key_events"]) if isinstance(d["key_events"], str) else d["key_events"]
            except (ValueError, SyntaxError):
                d["key_events"] = []
            by_anime[d["anime_name"]].append(d)
    for anime in by_anime:
        by_anime[anime].sort(key=lambda r: r["chapter_number"])
    return by_anime


def build_lore_cases() -> list[dict]:
    chapters = _load_chapters()
    cases = []

    # 20 regular LORE cases: 5 per anime, spread across early/mid/late chapters
    # so retrieval and the spoiler-cap logic get exercised at different depths.
    for anime in SUPPORTED_ANIME:
        chs = chapters[anime]
        n = len(chs)
        picks = [chs[int(n * f)] for f in (0.05, 0.25, 0.5, 0.75, 0.95)]
        for rec in picks:
            cases.append({
                "id": f"lore_{anime.replace(' ', '_').lower()}_{rec['chapter_number']}",
                "category": "LORE",
                "input": f"What happens in Chapter {rec['chapter_number']} of {anime}?",
                "kwargs": {"anime_name": anime, "spoiler_mode": True},
                "expected": {
                    "intents": ["LORE"],
                    "expected_anime": anime,
                    "expected_chapter": rec["chapter_number"],
                    "reference_facts": rec["key_events"],
                    "should_decline": False,
                },
            })

    # 5 spoiler-boundary cases: ask about a late chapter while capped well
    # before it (spoiler_mode=False) — the answer must NOT reveal it.
    boundary_anime = (SUPPORTED_ANIME * 2)[:5]  # all 4 once, + 1 repeat to reach 5
    for i, anime in enumerate(boundary_anime):
        chs = chapters[anime]
        n = len(chs)
        target = chs[int(n * 0.85)]
        cap = chs[max(0, int(n * 0.2))]["chapter_number"]
        cases.append({
            "id": f"lore_spoiler_block_{anime.replace(' ', '_').lower()}_{i}",
            "category": "LORE_SPOILER_BLOCK",
            "input": f"What happens in Chapter {target['chapter_number']} of {anime}?",
            "kwargs": {"anime_name": anime, "current_chapter": cap, "spoiler_mode": False},
            "expected": {
                "intents": ["LORE"],
                "expected_anime": anime,
                "expected_chapter": target["chapter_number"],
                "reference_facts": target["key_events"],
                "should_decline": True,  # must NOT reveal these facts
            },
        })

    return cases


# ── EPISODE_UPDATE cases — expected chapter cap computed via the real function ──

def build_episode_update_cases() -> list[dict]:
    picks = [
        ("Demon Slayer", 12), ("Jujutsu Kaisen", 20),
        ("Attack on Titan", 15), ("Chainsaw Man", 8),
    ]
    cases = []
    for anime, ep in picks:
        expected_cap = episode_to_chapter(anime, ep)
        cases.append({
            "id": f"episode_update_{anime.replace(' ', '_').lower()}_{ep}",
            "category": "EPISODE_UPDATE",
            "input": f"I'm caught up to episode {ep} of {anime}.",
            "kwargs": {},
            "expected": {
                "intents": ["EPISODE_UPDATE"],
                "expected_anime": anime,
                "expected_chapter_cap": expected_cap,
            },
        })
    return cases


# ── Hand-written cases ──────────────────────────────────────────────────────────

def build_recommend_cases() -> list[dict]:
    prompts = [
        "Recommend anime similar to Demon Slayer.",
        "What should I watch if I like Jujutsu Kaisen?",
        "Suggest something dark and psychological.",
        "Recommend anime with a strong found-family theme.",
        "What's a good isekai to watch?",
        "Recommend something similar to Attack on Titan but shorter.",
    ]
    return [{
        "id": f"recommend_{i}",
        "category": "RECOMMEND",
        "input": p,
        "kwargs": {"spoiler_mode": True},
        "expected": {"intents": ["RECOMMEND"], "should_decline": False},
    } for i, p in enumerate(prompts)]


def build_tool_cases() -> list[dict]:
    cases = [
        ("When does Jujutsu Kaisen air next?", "Jujutsu Kaisen", "schedule"),
        ("What's Demon Slayer's episode ratings graph look like?", "Demon Slayer", "ratings"),
        ("When's the next Attack on Titan episode airing?", "Attack on Titan", "schedule"),
        ("Show me the rating graph for Chainsaw Man.", "Chainsaw Man", "ratings"),
        ("What time does Chainsaw Man air?", "Chainsaw Man", "schedule"),
    ]
    return [{
        "id": f"tool_{anime.replace(' ', '_').lower()}_{kind}",
        "category": "TOOL",
        "input": msg,
        "kwargs": {"anime_name": anime, "spoiler_mode": True},
        "expected": {"intents": ["TOOL"], "expected_anime": anime, "tool_kind": kind},
    } for msg, anime, kind in cases]


def build_persona_cases() -> list[dict]:
    cases = [
        ("Talk like Gojo from now on.", "Satoru Gojo"),
        ("Be Levi.", "Levi Ackerman"),
        ("Pretend to be Tanjiro.", "Tanjiro Kamado"),
        ("Go back to normal.", "Default"),
    ]
    return [{
        "id": f"persona_{i}",
        "category": "PERSONA_SWITCH",
        "input": msg,
        "kwargs": {"persona": "Satoru Gojo" if expected == "Default" else "Default"},
        "expected": {"intents": ["PERSONA_SWITCH"], "expected_persona": expected},
    } for i, (msg, expected) in enumerate(cases)]


def build_general_cases() -> list[dict]:
    prompts = [
        "Hi there!",
        "Who's your favorite character?",
        "Is Chainsaw Man worth watching?",
        "What's the weather like today?",
        "Thanks for the help!",
        "Do you remember what anime I was asking about earlier?",
    ]
    return [{
        "id": f"general_{i}",
        "category": "GENERAL",
        "input": p,
        "kwargs": {"spoiler_mode": True},
        "expected": {"intents": ["GENERAL"]},
    } for i, p in enumerate(prompts)]


def build_compound_cases() -> list[dict]:
    # Directly encodes regression coverage for the bugs found and fixed
    # across the last three commits — a compound message must NOT collapse
    # to one intent, and an unsupported-anime part inside a compound
    # message must still be correctly refused.
    cases = [
        dict(id="compound_lore_tool", input="Tell me how Muzan was killed and when will the next episode of Demon Slayer air?",
             kwargs=dict(anime_name="Demon Slayer", spoiler_mode=True),
             expected=dict(intents=["LORE", "TOOL"])),
        dict(id="compound_recommend_tool", input="Recommend me anime like Chainsaw Man and also generate its rating graph.",
             kwargs=dict(anime_name="Chainsaw Man", spoiler_mode=True),
             expected=dict(intents=["RECOMMEND", "TOOL"])),
        dict(id="compound_general_tool", input="Hey, how's it going? Also when does Chainsaw Man air next?",
             kwargs=dict(anime_name="Chainsaw Man", spoiler_mode=True),
             expected=dict(intents=["GENERAL", "TOOL"])),
        dict(id="compound_general_lore", input="Hi! Also, who is Muzan?",
             kwargs=dict(anime_name="Demon Slayer", spoiler_mode=True),
             expected=dict(intents=["GENERAL", "LORE"])),
        dict(id="compound_unsupported_lore_tool", input="What happens in One Piece and when's the next JJK episode?",
             kwargs=dict(anime_name="", spoiler_mode=True),
             expected=dict(intents=["LORE", "TOOL"], unsupported_anime_in_lore=True)),
        dict(id="compound_frieren_recommend_lore", input="Recommend anime like Frieren and also who is Frieren as a character?",
             kwargs=dict(anime_name="", spoiler_mode=True),
             expected=dict(intents=["RECOMMEND", "LORE"], unsupported_anime_in_lore=True)),
        dict(id="compound_triple", input="How did Muzan die, recommend me similar anime, and when's the next JJK episode airing?",
             kwargs=dict(anime_name="Demon Slayer", spoiler_mode=True),
             expected=dict(intents=["LORE", "RECOMMEND", "TOOL"])),
        dict(id="compound_comma_only_two_tool", input="How did Levi lose his squad, what's the AOT rating graph, when's the next episode airing?",
             kwargs=dict(anime_name="Attack on Titan", spoiler_mode=True),
             expected=dict(intents=["LORE", "TOOL"])),
        dict(id="compound_same_anime_two_tool", input="When's Demon Slayer airing next, and what's its rating graph?",
             kwargs=dict(anime_name="Demon Slayer", spoiler_mode=True),
             expected=dict(intents=["TOOL"])),
    ]
    for c in cases:
        c["category"] = "COMPOUND"
    return cases


def main() -> None:
    all_cases = (
        build_lore_cases()
        + build_episode_update_cases()
        + build_recommend_cases()
        + build_tool_cases()
        + build_persona_cases()
        + build_general_cases()
        + build_compound_cases()
    )

    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(OUT_PATH, "w", encoding="utf-8") as f:
        for case in all_cases:
            f.write(json.dumps(case, ensure_ascii=False) + "\n")

    by_category: dict[str, int] = defaultdict(int)
    for case in all_cases:
        by_category[case["category"]] += 1

    print(f"Wrote {len(all_cases)} cases to {OUT_PATH}")
    for cat, count in sorted(by_category.items()):
        print(f"  {cat}: {count}")


if __name__ == "__main__":
    main()
